flixel_addons_ui_U.splitBitString = function(str) {
	var result = [];
	var arr = str.split("\n");
	var i = 0;
	while(i < arr.length) {
		var len = arr[i].length;
		var j = 0;
		while(j < len) {
			var char = arr[i].charAt(j);
			var num = Std.parseInt(char);
			result.push(num);
			++j;
		}
		++i;
	}
	return result;
};
