	,updateGroups: function(refresh) {
		if(refresh == null) {
			refresh = false;
		}
		var newGroup = null;
		switch(backend_ClientPrefs.data.groupSongsBy) {
		case "Alphabetically":
			newGroup = states_GroupType.ALPHABET;
			break;
		case "Character Mix":
			newGroup = states_GroupType.MIX;
			break;
		case "Modpack":
			newGroup = states_GroupType.MOD;
			break;
		default:
			newGroup = states_GroupType.DEFAULT;
		}
		if(newGroup != states_FreeplayState.searchGroup) {
			states_FreeplayState.searchGroup = newGroup;
			if(states_FreeplayState.searchGroup != null) {
				states_FreeplayState.set_searchGroupValue(0);
			}
		}
		switch(states_FreeplayState.searchGroup._hx_index) {
		case 1:
			states_FreeplayState.searchGroupVList = ["ab","cd","ef","gh","ij","kl","mn","op","qr","st","uv","wx","yz"];
			break;
		case 2:
			states_FreeplayState.searchGroupVList = this.modList;
			break;
		case 3:
			var _g = [];
			var h = this.charsWeeksLoaded.h;
			var char_h = h;
			var char_keys = Object.keys(h);
			var char_length = char_keys.length;
			var char_current = 0;
			while(char_current < char_length) {
				var char = char_keys[char_current++];
				_g.push(char);
			}
			states_FreeplayState.searchGroupVList = ["default"].concat(_g);
			break;
		default:
			states_FreeplayState.searchGroupVList = ["All","Favorites","Hidden"];
		}
		if(!refresh) {
			if(states_FreeplayState.searchGroup == states_GroupType.MIX && backend_ClientPrefs.data.currentSkin != null) {
				var skinIndex = states_FreeplayState.searchGroupVList.indexOf(backend_ClientPrefs.data.currentSkin[0]);
				if(skinIndex != -1) {
					states_FreeplayState.set_searchGroupValue(skinIndex);
				}
			}
		}
		if(states_FreeplayState.get_searchGroupValue() < 0) {
			states_FreeplayState.set_searchGroupValue(0);
		}
		if(states_FreeplayState.get_searchGroupValue() > states_FreeplayState.searchGroupVList.length - 1) {
			states_FreeplayState.set_searchGroupValue(states_FreeplayState.searchGroupVList.length - 1);
		}
		this.search(!refresh);
		this.updateGroupTitle();
	}
