	,openSubState: function(SubState) {
		if(!((SubState) instanceof backend_CustomFadeTransition)) {
			this.hudCamera.set_visible(false);
			this.itemsCamera.set_visible(false);
		}
		backend_MusicBeatState.prototype.openSubState.call(this,SubState);
	}
	,closeSubState: function() {
		this.curPage = 0;
		this.changeSelection(0,false);
		if(this.selected) {
			this.changeDiff();
		}
		if(this._substateIsModifiers) {
			this.set_leaderboardTimer(0);
			this._substateIsModifiers = false;
		}
		this.persistentUpdate = true;
		if(!((this.subState) instanceof backend_CustomFadeTransition)) {
			this.hudCamera.set_visible(true);
			this.itemsCamera.set_visible(true);
		}
		backend_MusicBeatState.prototype.closeSubState.call(this);
	}
