	,set_songSpeed: function(value) {
		if(this.generatedMusic) {
			var ratio = value / this.songSpeed;
			if(ratio != 1) {
				var _g = 0;
				var _g1 = this.notes.members;
				while(_g < _g1.length) {
					var note = _g1[_g];
					++_g;
					note.resizeByRatio(ratio);
				}
				var _g = 0;
				var _g1 = this.unspawnNotes;
				while(_g < _g1.length) {
					var note = _g1[_g];
					++_g;
					note.resizeByRatio(ratio);
				}
			}
		}
		this.songSpeed = value;
		this.noteKillOffset = Math.max(backend_Conductor.stepCrochet,350 / this.songSpeed * this.playbackRate);
		return value;
	}
