	,clearNotesBefore: function(time) {
		if(this.replayPlayer != null) {
			this.replayPlayer.timeJump(time);
		}
		if(this.nicomments != null) {
			this.nicomments.timeJump(time);
		}
		var i = this.unspawnNotes.length - 1;
		while(i >= 0) {
			var daNote = this.unspawnNotes[i];
			if(daNote.strumTime - 350 < time) {
				daNote.set_active(false);
				daNote.set_visible(false);
				daNote.ignoreNote = true;
				daNote.kill();
				HxOverrides.remove(this.unspawnNotes,daNote);
				daNote.destroy();
			}
			--i;
		}
		i = this.notes.length - 1;
		while(i >= 0) {
			var daNote = this.notes.members[i];
			if(daNote.strumTime - 350 < time) {
				daNote.set_active(false);
				daNote.set_visible(false);
				daNote.ignoreNote = true;
				daNote.kill();
				this.notes.remove(daNote,true);
				daNote.destroy();
			}
			--i;
		}
	}
	,updateScore: function(miss,skipRest) {
		if(skipRest == null) {
			skipRest = false;
		}
		if(miss == null) {
			miss = false;
		}
		var _gthis = this;
		var points = flixel_math_FlxMath.roundDecimal(online_FunkinPoints.fcalcFP(this.ratingPercent,this.songMisses,this.songDensity,this.totalNotesHit,this.maxCombo),2);
		if(points != this.songPoints) {
			this.songPoints = points;
			online_GameClient.send("updateSongFP",Math.floor(this.songPoints));
			if(this.totalPlayed != 0) {
				var maxPoints = online_FunkinPoints.calcFP(1,0,this.songDensity,this.totalPlayed,this.totalPlayed);
				this.pointsPercent = Math.min(1,Math.max(0,points / maxPoints));
			}
			this.resetRPC(true);
		}
		this.songPoints = points;
		var scoreTextObject = this.scoreTxt;
		if(online_GameClient.client != null || online_GameClient.reconnecting) {
			this.updateScoreSID(online_GameClient.room.sessionId);
			return;
		}
		var tmp = this.ratingName;
		var str = tmp != null ? tmp : "?";
		if(this.totalPlayed != 0) {
			var percent = backend_CoolUtil.floorDecimal(this.ratingPercent * 100,2);
			str += " (" + percent + "%) - " + this.ratingFC;
		}
		scoreTextObject.set_text("Score: " + flixel_util_FlxStringUtil.formatMoney(this.songScore,false) + " | Misses: " + this.songMisses + " | Rating: " + str);
		if(skipRest) {
			if(backend_ClientPrefs.data.showFP) {
				this.addFPToScoreTxt(scoreTextObject);
			}
			return;
		}
		if(backend_ClientPrefs.data.scoreZoom && !miss && !this.cpuControlled) {
			if(this.scoreTxtTween != null) {
				this.scoreTxtTween.cancel();
			}
			scoreTextObject.scale.set_x(1.075);
			scoreTextObject.scale.set_y(1.075);
			this.scoreTxtTween = flixel_tweens_FlxTween.tween(scoreTextObject.scale,{ x : 1, y : 1},0.2,{ onComplete : function(twn) {
				_gthis.scoreTxtTween = null;
			}});
		}
		this.callOnScripts("onUpdateScore",[miss]);
		if(backend_ClientPrefs.data.showFP) {
			this.addFPToScoreTxt(scoreTextObject);
		}
	}
	,addFPToScoreTxt: function(scoreTextObject) {
		if(backend_ClientPrefs.data.newFPPreview) {
			scoreTextObject.set_text(scoreTextObject.text + (" | FP: " + this.songPoints + (" (V5: " + flixel_math_FlxMath.roundDecimal(online_FunkinPoints.devFP(this.ratingPercent,this.songMisses,this.songDensity,this.totalNotesHit,this.maxCombo,this.difficultyInfo),2) + ")")));
		} else {
			scoreTextObject.set_text(scoreTextObject.text + (" | FP: " + this.songPoints + (" (" + backend_CoolUtil.floorDecimal(this.pointsPercent * 100,1) + "%)")));
		}
	}
	,setSongTime: function(time) {
		if(time < 0) {
			time = 0;
		}
		flixel_FlxG.sound.music.pause();
		this.vocals.pause();
		this.opponentVocals.pause();
		flixel_FlxG.sound.music.set_time(time);
		flixel_FlxG.sound.music.set_pitch(this.playbackRate);
		flixel_FlxG.sound.music.play();
		if(backend_Conductor.songPosition <= this.vocals._length) {
			this.vocals.set_time(time);
			this.vocals.set_pitch(this.playbackRate);
		}
		if(backend_Conductor.songPosition <= this.opponentVocals._length) {
			this.opponentVocals.set_time(time);
			this.opponentVocals.set_pitch(this.playbackRate);
		}
		this.vocals.play();
		this.opponentVocals.play();
		backend_Conductor.songPosition = time;
	}
	,startNextDialogue: function() {
		this.dialogueCount++;
		this.callOnScripts("onNextDialogue",[this.dialogueCount]);
	}
	,skipDialogue: function() {
		this.callOnScripts("onSkipDialogue",[this.dialogueCount]);
	}
	,getPresencePoints: function() {
		if(this.songPoints == 0) {
			return "";
		}
		if(this.songPoints < 0) {
			var aasss = ("" + this.songPoints).split("");
			aasss.splice(1,0," ");
			return " - " + aasss.join("") + "FP";
		}
		return " - " + this.songPoints + "FP";
	}
