	,eventPushed: function(event) {
		this.eventPushedUnique(event);
		if(this.eventsPushed.indexOf(event.event) != -1) {
			return;
		}
		this.stagesFunc(function(stage) {
			stage.eventPushed(event);
		});
		this.eventsPushed.push(event.event);
	}
	,eventPushedUnique: function(event) {
		switch(event.event) {
		case "Change Character":
			var charType = 0;
			switch(event.value1.toLowerCase()) {
			case "0":case "dad":case "opponent":
				charType = 1;
				break;
			case "1":case "gf":case "girlfriend":
				charType = 2;
				break;
			default:
				var val1 = Std.parseInt(event.value1);
				if(isNaN(val1)) {
					val1 = 0;
				}
				charType = val1;
			}
			var newCharacter = event.value2;
			this.addCharacterToList(newCharacter,charType);
			break;
		case "Focus Camera":
			this.sectionCameraMovement = false;
			break;
		case "Play Sound":
			this.precacheList.h[event.value1] = "sound";
			backend_Paths.sound(event.value1);
			break;
		case "Set Health Icon":
			new objects_HealthIcon(event.value2);
			break;
		}
		this.stagesFunc(function(stage) {
			stage.eventPushedUnique(event);
		});
	}
	,eventEarlyTrigger: function(event) {
		var returnedValue = this.callOnScripts("eventEarlyTrigger",[event.event,event.value1,event.value2,event.strumTime],true,[],[0]);
		if(returnedValue != null && returnedValue != 0 && returnedValue != psychlua_FunkinLua.Function_Continue) {
			return returnedValue;
		}
		if(event.event == "Kill Henchmen") {
			return 280;
		}
		return 0;
	}
