		if(backend_Difficulty.list[num == null ? states_PlayState.storyDifficulty : num] != "Erect") {
			var num = null;
			tmp = backend_Difficulty.list[num == null ? states_PlayState.storyDifficulty : num] == "Nightmare";
		} else {
			tmp = true;
		}
