	,loadHealthIconFromCharacter: function(char) {
		var characterPath = "characters/" + char + ".json";
		var path = backend_Paths.modFolders(characterPath);
		if(!sys_FileSystem.exists(path)) {
			var file = characterPath;
			if(file == null) {
				file = "";
			}
			path = "assets/" + file;
		}
		if(!sys_FileSystem.exists(path)) {
			var file = "characters/" + objects_Character.DEFAULT_CHARACTER + ".json";
			if(file == null) {
				file = "";
			}
			path = "assets/" + file;
		}
		var rawJson = sys_io_File.getContent(path);
		var json = tjson_TJSON.parse(rawJson);
		return json.healthicon;
	}
