	,setupRainShader: function() {
		this.rainShader = new shaders_RainShader();
		this.rainShader.set_scale(flixel_FlxG.height / 200);
		switch(this.game.songName) {
		case "2hot":
			this.rainShaderStartIntensity = 0.2;
			this.rainShaderEndIntensity = 0.4;
			break;
		case "darnell":
			this.rainShaderStartIntensity = 0;
			this.rainShaderEndIntensity = 0.1;
			break;
		case "lit-up":
			this.rainShaderStartIntensity = 0.1;
			this.rainShaderEndIntensity = 0.2;
			break;
		}
		this.rainShader.set_intensity(this.rainShaderStartIntensity);
		flixel_FlxG.camera.setFilters([new openfl_filters_ShaderFilter(this.rainShader)]);
	}
	,currentNeneState: null
	,animationFinished: null
	,update: function(elapsed) {
		if(this.scrollingSky != null) {
			var fh = this.scrollingSky;
			fh.set_scrollX(fh.scrollX - elapsed * 22);
		}
		if(this.rainShader != null) {
			var remappedIntensityValue = flixel_math_FlxMath.remapToRange(backend_Conductor.songPosition,0,flixel_FlxG.sound.music != null ? flixel_FlxG.sound.music._length : 0,this.rainShaderStartIntensity,this.rainShaderEndIntensity);
			this.rainShader.set_intensity(remappedIntensityValue);
			this.rainShader.updateViewInfo(flixel_FlxG.width,flixel_FlxG.height,flixel_FlxG.camera);
			this.rainShader.update(elapsed);
		}
		if(this.game.gf == null || !this.game.startedCountdown) {
			return;
		}
		this.animationFinished = this.game.gf.isAnimationFinished();
		this.transitionState();
	}
	,transitionState: function() {
		if(!StringTools.startsWith(this.game.gf.curCharacter,"nene")) {
			return;
		}
		switch(this.currentNeneState._hx_index) {
		case 0:
			if(this.game.health <= this.VULTURE_THRESHOLD) {
				this.currentNeneState = states_stages_NeneState.STATE_PRE_RAISE;
				this.game.gf.skipDance = true;
			}
			break;
		case 1:
			if(this.game.health > this.VULTURE_THRESHOLD) {
				this.currentNeneState = states_stages_NeneState.STATE_DEFAULT;
				this.game.gf.skipDance = false;
			} else if(this.animationFinished) {
				this.currentNeneState = states_stages_NeneState.STATE_RAISE;
				this.game.gf.playAnim("raiseKnife");
				this.game.gf.skipDance = true;
				this.game.gf.danced = true;
				this.animationFinished = false;
			}
			break;
		case 2:
			if(this.animationFinished) {
				this.currentNeneState = states_stages_NeneState.STATE_READY;
				this.animationFinished = false;
			}
			break;
		case 3:
			if(this.game.health > this.VULTURE_THRESHOLD) {
				this.currentNeneState = states_stages_NeneState.STATE_LOWER;
				this.game.gf.playAnim("lowerKnife");
			}
			break;
		case 4:
			if(this.animationFinished) {
				this.currentNeneState = states_stages_NeneState.STATE_DEFAULT;
				this.animationFinished = false;
				this.game.gf.skipDance = false;
			}
			break;
		}
	}
