	,goodNoteHit: function(note) {
		var _gthis = this;
		switch(this.game.combo) {
		case 50:case 100:case 200:
			var animToPlay = "combo" + Std.string(this.game.combo);
			if(this.game.gf.animation.exists(animToPlay)) {
				this.game.gf.playAnim(animToPlay);
				this.game.gf.specialAnim = true;
			}
			break;
		}
		switch(note.noteType) {
		case "weekend-1-cockgun":
			this.game.boyfriend.holdTimer = 0;
			this.game.boyfriend.playAnim("cock",true);
			this.game.boyfriend.specialAnim = true;
			this.gunPrepSnd.play();
			this.game.boyfriend.animation.callback = function(name,frameNumber,frameIndex) {
				if(name == "cock") {
					if(frameNumber == 3) {
						_gthis.game.boyfriend.animation.callback = null;
						_gthis.createCasing();
					}
				} else {
					_gthis.game.boyfriend.animation.callback = null;
				}
			};
			this.game.notes.forEachAlive(function(note) {
				if(note.noteType == "weekend-1-firegun") {
					note.blockHit = false;
				}
			});
			this.showPicoFade();
			break;
		case "weekend-1-firegun":
			this.game.boyfriend.holdTimer = 0;
			this.game.boyfriend.playAnim("shoot",true);
			this.game.boyfriend.specialAnim = true;
			flixel_FlxG.sound.play(backend_Paths.sound("shots/shot" + flixel_FlxG.random.int(1,4),null));
			this.spraycan.playCanShot();
			new flixel_util_FlxTimer().start(0.0416666666666666644,function(tmr) {
				_gthis.darkenStageProps();
			});
			break;
		}
	}
	,createCasing: function() {
		if(backend_ClientPrefs.data.lowQuality) {
			return;
		}
		var casing = new flixel_FlxSprite(this.game.boyfriend.x + 250,this.game.boyfriend.y + 100);
		casing.set_frames(this.casingFrames);
		casing.animation.addByPrefix("pop","Pop0",24,false);
		casing.animation.addByPrefix("idle","Bullet0",24,true);
		casing.animation.play("pop",true);
		casing.animation.callback = function(name,frameNumber,frameIndex) {
			if(name == "pop" && frameNumber == 40) {
				casing.set_x(casing.x + casing.frame.offset.x - 1);
				casing.set_y(casing.y + casing.frame.offset.y + 1);
				casing.set_angle(125.1);
				var randomFactorA = flixel_FlxG.random.float(3,10);
				var randomFactorB = flixel_FlxG.random.float(1.0,2.0);
				casing.velocity.set_x(20 * randomFactorB);
				casing.drag.set_x(randomFactorA * randomFactorB);
				casing.angularVelocity = 100;
				casing.angularDrag = casing.drag.x / casing.velocity.x * 100;
				casing.animation.play("idle");
				casing.animation.callback = null;
			}
		};
		this.casingGroup.add(casing);
	}
